export const ngMolarItems=ngMolarCoordinates.map(([number,layer,north,east])=>{
 const id='ng-molar-'+String(number).padStart(3,'0');
 const lng=(east/1254*200000-100000)/360000*registration[0]+registration[1];
 const lat=(north/1254*200000-100000)/360000*registration[2]+registration[3];
 const route=ngMolarRoutes[number-1],underwater=layer===2;
 return {id,pin:id,number,group:'ng-molars',category:'ng-milk',name:'NG+ '+(underwater?'水下乳牙':'乳牙')+' '+String(number).padStart(3,'0'),officialName:'NG+ Milk Molar '+number,
 section:underwater?'水下候選點':layer===3?'洞穴／結構內候選點':'地表／高處候選點',note:route,locationDescription:route,point:[lng,lat],underwater,
 access:{layer:number===1?'孩童箱外側':underwater?'水下':layer===3?'洞穴／結構內':'地表／高處',route,entry:ngEntryFor(number),prep:underwater?'泡泡頭盔、水蟲鰭足、二階以上水下匕首、潛水提燈':'昆蟲鎚或黑牛甲蟲鎚；高處另備蒲公英絨毛',source:ngMolarSource}};
});
export const ngMolarById=new Map(ngMolarItems.map(item=>[item.id,item]));
